import { readFileSync } from 'node:fs'
import { randomUUID } from 'node:crypto'
import { createClient } from '@supabase/supabase-js'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { handleEconomicEdit, type EconomicDependencies } from '@/lib/edit-v4/economic/handler'

// Opt-in only: generated by the disposable Supabase validation driver, never a cloud project.
const configPath = process.env.EDIT_V4_POSTGREST_TEST_CONFIG
describe.skipIf(!configPath)('economic handler through isolated Supabase HTTP', () => {
  let config: { pr327SyntheticOnly: boolean; apiUrl: string; serviceKey: string; owner: string }
  let nativeFetch: typeof fetch

  beforeEach(() => {
    config = JSON.parse(readFileSync(configPath!, 'utf8'))
    expect(config.pr327SyntheticOnly).toBe(true)
    expect(new URL(config.apiUrl).origin).toBe('http://127.0.0.1:56321')
    nativeFetch = globalThis.fetch
    vi.stubGlobal('fetch', (input: Parameters<typeof fetch>[0], init?: RequestInit) => {
      const url = new URL(typeof input === 'string' ? input : input instanceof URL ? input.href : input.url)
      if (url.origin !== config.apiUrl) throw new Error('Only the isolated Supabase HTTP endpoint is permitted')
      return nativeFetch(input, init)
    })
    // This switch is scoped to this test process. Inference and uploads are replaced below.
    vi.stubEnv('EDIT_V4_ECONOMIC_PAID_CALLS', '1')
    vi.stubEnv('NEXT_PUBLIC_SUPABASE_URL', config.apiUrl)
  })
  afterEach(() => { vi.unstubAllGlobals(); vi.unstubAllEnvs() })

  async function exercise(loseResponse: boolean) {
    const options = { auth: { persistSession: false, autoRefreshToken: false } }
    const db = createClient(config.apiUrl, config.serviceKey, options)
    const asset = (name: string) => `${config.apiUrl}/storage/v1/object/public/space-mestres/${config.owner}/${name}.png`
    const input = { userId: config.owner, clientRequestId: randomUUID(), selectionConfirmed: true, charge: true,
      request: { action: 'swap_material' as const, sourceImageUrl: asset('source'), maskUrl: asset('mask'), instruction: 'Synthetic navy panel', preservation: 'maximum' as const, intensity: 'standard' as const, edgeSoftness: 'hard' as const, references: [] } }
    const binding = { sourceHash: 'a'.repeat(64), maskHash: 'b'.repeat(64), requestHash: 'c'.repeat(64) }
    const candidateHash = 'd'.repeat(64)
    const result: Awaited<ReturnType<EconomicDependencies['run']>> = {
      buffer: Buffer.from('synthetic-output'), binding, candidateHash, engine: 'local_color', model: 'local-linear-paint-v1',
      ledger: [
        { stage: 'reader', provider: 'openai', model: 'gpt-6-luna', status: 'completed', knownUsd: .001, reserveUsd: .004, requestId: 'synthetic-reader', durationMs: 1 },
        { stage: 'judge', provider: 'openai', model: 'gpt-6-luna', status: 'completed', knownUsd: .001, reserveUsd: .004, requestId: 'synthetic-judge', durationMs: 1 },
      ],
      accountedUsd: .01, output: { width: 100, height: 100 }, metrics: { maskCoverage: .2, outsideChangedPixels: 0 },
      verdict: { ...binding, candidateHash, requestApplied: true, correctTarget: true, geometryPreserved: true, protectedPreserved: true, artifactFree: true, referenceFollowed: null, uncertain: false,
        evidence: { requestApplied: 'synthetic', correctTarget: 'synthetic', geometryPreserved: 'synthetic', protectedPreserved: 'synthetic', artifactFree: 'synthetic' } },
    }
    const pipeline = vi.fn<EconomicDependencies['run']>(async ({ checkpoint }) => { await checkpoint(result.ledger); return result })
    const upload = vi.fn().mockResolvedValue(asset('result'))
    let lostResponses = 0
    const endpoint = createClient(config.apiUrl, config.serviceKey, { ...options, global: { fetch: async (url, init) => {
      const response = await globalThis.fetch(url, init)
      if (loseResponse && String(url).includes('/rpc/finish_edit_v4_economic')) {
        await response.arrayBuffer(); lostResponses++; throw new TypeError('Synthetic response lost after commit')
      }
      return response
    } } })
    const before = await db.from('profiles').select('credits').eq('id', config.owner).single()
    expect(before.error).toBeNull()
    const deps = { admin: () => endpoint, run: pipeline, upload }
    const first = await handleEconomicEdit(input, deps), body = await first.json()
    if (loseResponse) {
      expect(first.status).toBe(503)
      expect(body).toMatchObject({ completion_pending: true, terminal: false })
      expect(body.result_url).toBeUndefined()
      expect(lostResponses).toBe(1)
    } else {
      expect(first.status).toBe(200)
      expect(body).toMatchObject({ rejected: false, nodes_cost: 10, charge: { debited: true } })
    }
    const replay = await handleEconomicEdit(input, deps)
    expect(replay.status).toBe(200)
    expect(await replay.json()).toMatchObject({ replayed: true, nodes_cost: 10, result_url: asset('result'), charge: { debited: false } })
    expect(pipeline).toHaveBeenCalledTimes(1)
    expect(upload).toHaveBeenCalledTimes(1)
    const after = await db.from('profiles').select('credits').eq('id', config.owner).single()
    expect(after.error).toBeNull()
    expect(after.data!.credits).toBe(before.data!.credits - 10)
    const history = await db.from('edit_v3_jobs').select('status,charged').eq('user_id', config.owner).eq('client_request_id', input.clientRequestId).single()
    expect(history.error).toBeNull()
    expect(history.data).toEqual({ status: 'completed', charged: true })
  }

  it('persists checkpoints and completes once through the real SDK and HTTP API', () => exercise(false))
  it('reconciles a lost committed completion without rerunning or charging again', () => exercise(true))
})
